INSERT INTO "legacy_library_import" (email, movie_id, title, poster_path, overview, watchlisted, score, notes, original_title, year, director, genres, runtime_minutes, country, backdrop_path, trailer_url, external_rating, external_votes, watched_at, preference, magic_factor, pinned_position, added_at) VALUES
('marco.corradino@gmail.com', 13, 'Forrest Gump', '/pGZqc9jQ6F8klQZKm37NAAMH70o.jpg', 'Forrest Gump - un ragazzo non proprio idiota, ma dal basso coefficiente d''intelligenza - racconta la sua storia a coloro che, uno dopo l''altro, si siedono vicino a lui in attesa dell''autobus. È stato in Vietnam, ha stretto la mano a tre presidenti, ha incontrato Elvis, ha assistito ai movimenti studenteschi, ha casualmente fatto esplodere il Watergate, ha suggerito le parole di "Imagine" a John Lennon e per tutta la vita è stato innamorato di una ragazza conosciuta fin da bambino.', false, 8, '', 'Forrest Gump', 1994, 'Robert Zemeckis', 'Commedia, Dramma, Romance', 137, 'US', '/67HggiWaP9ZLv5sPYmyRV37yAJM.jpg', 'https://www.youtube.com/watch?v=39gieYxSfAQ', 8.463, 28910, '2025-12-08', 'loved', 0, NULL, '2025-12-08T15:05:50.231000+00'),
('marco.corradino@gmail.com', 70, 'Million Dollar Baby', '/3ehWHEKe54gTpYoTZ19q2qRCCyH.jpg', 'Maggie Fitzgerald fa la cameriera, ha passato i trent''anni ma ancora sogna di affermarsi come boxeuse, e ha anche incontrato l''allenatore che fa al caso suo. Peccato che Frankie Dunn non voglia saperne di allenare una donna...', false, 10, '', 'Million Dollar Baby', 2004, 'Clint Eastwood', 'Dramma', 132, 'US', '/oGMomeS7bE43eN8SGJUaKvQnmud.jpg', 'https://www.youtube.com/watch?v=-LiqFRnwmas', 7.953, 10571, '2026-09-11', 'loved', 2, 2, '2026-09-11T17:02:34.545000+00'),
('marco.corradino@gmail.com', 77, 'Memento', '/wTmmN7Zbs9L28ganGOp5DHHxuda.jpg', 'Memento è l''imperativo del verbo difettivo latino "memini, isse" e può essere tradotto con "ricordati", che è la parola chiave del secondo lungometraggio di Christopher Nolan. Intorno a questo principio ruota infatti l''intera vicenda, non raccontata in modo lineare, ma attraverso un apparente caos che incarna il punto di vista del personaggio principale, Leonard Shelby, affetto da una particolare forma di amnesia, che lascia intatti i vecchi ricordi ma comporta la perdita della memoria breve. Attraverso un''affannosa ricerca compiuta per mezzo dell''azione e della scrittura, che serve a registrare ciò di cui la percezione non può farsi sicuro garante, il detective Shelby cerca l''assassino della moglie, l''ultimo ricordo che "non riesce a ricordare di dimenticare", in una labirintica realtà continuamente riazzerata e in cui non si può mai pronunciare l''ultima parola.', false, 8, '', 'Memento', 2000, 'Christopher Nolan', 'Mistero, Thriller', 113, 'US', '/8pwCb7amg8Tvr9FZZJGt7J4OwLV.jpg', 'https://www.youtube.com/watch?v=Kf9mns4Wz1w', 8.2, 15708, '2026-01-14', 'liked', 0, NULL, '2026-01-13T17:24:36.328000+00'),
('marco.corradino@gmail.com', 120, 'Il Signore degli Anelli - La compagnia dell''anello', '/iZTDPQYgr3rhL7hPIYFt17ATp8.jpg', 'Bilbo Baggins ha deciso di celebrare il suo centoundicesimo compleanno in maniera molto particolare;alla fine della festa, abbandona parenti, amici, conoscenti e il suo affezionato nipote Frodo, cui lascia ogni cosa. Lo stregone Gandalf insiste perché lo hobbit lasci a Frodo anche il suo anello magico, su cui intende tenere un occhio vigile e fare alcune ricerche, perché potrebbe celare un mistero più inquietante di quanto non sembri. E così è; quello di Bilbo è l''Unico Anello, l''Anello per domarli, il cuore del potere del malefico Signore Oscuro Sauron, che sta tornando a tessere le sue trame di conquista e distruzione. Per impedirgli di vedere realizzato il suo sanguinoso disegno, l''anello dovrà essere distrutto, cosa possibile soltanto nella fornace di Monte Fato, dove Sauron, secoli prima, lo forgiò.', false, 7, '', 'The Lord of the Rings: The Fellowship of the Ring', 2001, 'Peter Jackson', 'Avventura, Fantasy, Azione', 179, 'NZ', '/x2RS3uTcsJJ9IfjNPcgDmukoEcQ.jpg', 'https://www.youtube.com/watch?v=Oiz8siG8OXA', 8.4, 26808, '2026-01-13', 'liked', 0, NULL, '2026-01-13T16:38:41.863000+00'),
('marco.corradino@gmail.com', 121, 'Il Signore degli Anelli - Le due torri', '/fVKewiBPcY2dQujYEsnQmQ7lfRZ.jpg', 'La Compagnia dell''Anello è divisa, e ogni speranza è riposta ora in Frodo e Sam, che stanno tentando di attraversare non visti i confini di Mordor, tallonati dall''infido Gollum: Aragorn, Gimli e Legolas sono invece sulle tracce di Merry e Pipino, rapiti dagli Uruk-Hai di Saruman e in grave pericolo di vita. Attraverso alterne vicende, raggiungeranno la terra di Rohan e aiuteranno il Re Theoden nella sua guerra contro il traditore Saruman...', false, 7, '', 'The Lord of the Rings: The Two Towers', 2002, 'Peter Jackson', 'Avventura, Fantasy, Azione', 180, 'NZ', '/kWYfW2Re0rUDE6IHhy4CRuKWeFr.jpg', 'https://www.youtube.com/watch?v=O8im5qfCepI', 8.411, 23152, '2025-12-10', 'liked', 0, NULL, '2025-12-10T17:07:30.857000+00'),
('marco.corradino@gmail.com', 122, 'Il Signore degli Anelli - Il ritorno del re', '/96XilLzI7bijsCG4l7oW6I62oad.jpg', 'Le forze di Sauron hanno attaccato la capitale di Gondor, Minas Tirith, nel suo assedio finale contro l''umanità. Tenuto da un debole sovrintendente, quello che una volta era un fastoso regno non ha mai avuto così bisogno del proprio re. Mentre Gandalf tenta disperatamente di spingere lo smembrato esercito di Gondor ad agire, Thèoden si unisce ai guerrieri di Rohan per combattere assieme a loro. Pieno di coraggio e di appassionata lealtà, l''esercito degli umani non riesce però a tener testa alle numerosissime legioni nemiche che giungono su tutto il regno. Ogni vittoria è accompagnata da un grande sacrificio. Malgrado le numerose perdite, la Compagnia si lancia verso la più grande battaglia mai affrontata, unita dall''unico scopo di riuscire a tenere Sauron distratto e dare a Frodo una occasione per portare a termine la sua spedizione...', false, 8, '', 'The Lord of the Rings: The Return of the King', 2003, 'Peter Jackson', 'Avventura, Fantasy, Azione', 201, 'NZ', '/2u7zbn8EudG6kLlBzUYqP8RyFU4.jpg', 'https://www.youtube.com/watch?v=dezthH3eGw0', 8.491, 25718, '2025-12-08', 'loved', 0, NULL, '2025-12-08T15:06:48.677000+00'),
('marco.corradino@gmail.com', 155, 'Il cavaliere oscuro', '/1hWiGdsoG7p1Dyckcnwiobenu1g.jpg', 'Il crimine organizzato a Gotham City ha le ore contate. Batman, il tenente Gordon, il nuovo Procuratore Distrettuale e alcuni improbabili epigoni dell''Uomo Pipistrello in imbottiture da hockey hanno dichiarato guerra ai criminali. La loro fortuna e i loro dollari, accumulati in una banca di massima sicurezza, vengono rubati da Joker, un pagliaccio sadico e mascherato che getterà la città nel disordine e nell''anarchia. Riempite le tasche di lame, polvere da sparo e lanugine, Joker sfiderà il cavaliere oscuro di Bruce Wayne e rivelerà il lato oscuro di Harvey Dent, l''eroe procuratore che applica la giustizia e agisce a volto scoperto.', false, 8, '', 'The Dark Knight', 2008, 'Christopher Nolan', 'Dramma, Azione, Crime, Thriller', 146, 'GB', '/dqK9Hag1054tghRQSqLSfrkvQnA.jpg', 'https://www.youtube.com/watch?v=dfwuVmue_3E', 8.524, 34794, '2025-12-10', 'loved', 0, NULL, '2025-12-10T19:47:21.129000+00'),
('marco.corradino@gmail.com', 194, 'Il favoloso mondo di Amélie', '/ugVnbzXJugaI83XHIvBNMsXnC35.jpg', 'Amélie cresce in provincia, siamo in Francia. Suo padre è un medico fin troppo originale: visita ogni mese la figlia, che si agita ogni volta, e crede che sia malata di cuore. La madre, uscita dalla chiesa, viene schiacciata da una suicida. Più grande la ragazza va a Parigi. Fa la cameriera e incontra tanta gente. Il 31 agosto 1997 è il giorno decisivo della sua vita: vede in tv il servizio dulla morte di lady Diana, le cade di mano un tappo di bottiglia che finisce sotto una piastrella, dove Amélie trova una vecchia scatola di cianfrusaglie (figurine, la foto di un calciatore, un ciclista di ferro). Si mette in testa di rintracciare il proprietario, che a quel punto avrà una cinquantina d''anni. Lo trova, gli restituisce il "ricordo" e gli cambia la vita.', false, 7, '', 'Le Fabuleux Destin d''Amélie Poulain', 2001, 'Jean-Pierre Jeunet', 'Commedia, Romance', 122, 'FR', '/6n53UI4mX9QMfe2S0Pgt8mGebY1.jpg', 'https://www.youtube.com/watch?v=go8KLBPndOs', 7.914, 12120, '2026-01-13', 'liked', 0, NULL, '2026-01-13T17:05:07.965000+00'),
('marco.corradino@gmail.com', 238, 'Il padrino', '/hGgz5ho658NECzErDayV5FQTemy.jpg', 'Anni Quaranta. Come è consuetudine, durante il rinfresco per festeggiare le nozze della figlia Conny con Carlo, il "padrino" don Vito Corleone promette assistenza e protezione a familiari e amici. Invia il figliastro Tom Hagen in California per convincere in ogni modo il produttore Jack Woltz a scritturare il cantante Johnny nel suo prossimo film. Woltz non acconsente. Tom allora lo costringe ad accettare con un "avvertimento": l''uccisione del suo cavallo di razza preferito. Sollozzo, a nome della potente "famiglia" Tartaglia, chiede a Corleone finanziamenti e appoggi per il traffico di droga. Il rifiuto scatena una lotta cruenta tra le due cosche: lo stesso don Vito viene ferito gravemente; il figlio minore Michael lo salva da un secondo attentato. Michael, poi, scavalcando l''irruento fratello Sonny e Tom, temporeggiatore, organizza un incontro con Sollozzo e con il corrotto capitano di polizia McCluskey uccidendoli entrambi.', false, 8, '', 'The Godfather', 1972, 'Francis Ford Coppola', 'Dramma, Crime', 175, 'US', '/39rtAdg3yx6IDxRg0ZLXefv0aPY.jpg', 'https://www.youtube.com/watch?v=9NoJZeytdqE', 8.685, 22128, '2025-12-08', 'loved', 0, NULL, '2025-12-08T15:07:00.650000+00'),
('marco.corradino@gmail.com', 240, 'Il padrino - Parte II', '/23NNNNLzaLnyTxwcuj680R7iBFH.jpg', 'Il film tratta della giovinezza e dei primi passi nel mondo del crimine di Vito Corleone, e delle difficoltà cinquant''anni più tardi di suo figlio, Michael, a mantenere in piedi l''impero Corleone. Il tutto tra vicende di emigrazione, tradimenti familiari, inchieste governative e affari.', false, 8, '', 'The Godfather Part II', 1974, 'Francis Ford Coppola', 'Dramma, Crime', 200, 'US', '/14icRpwdgpHEHxt7Cn5hr2RQEsF.jpg', 'https://www.youtube.com/watch?v=me9ATu6Lc3c', 8.571, 13378, '2025-12-08', 'loved', 0, NULL, '2025-12-08T15:07:09.671000+00'),
('marco.corradino@gmail.com', 272, 'Batman Begins', '/8E0rBGWnsNN9lUNcJGN7QMFja2O.jpg', 'Bruce Wayne, figlio di un illuminato filantropo di Gotham City, vede i suoi genitori assassinati da un rapinatore. Incapace di liberarsi del senso di colpa, inizia un vagabondaggio che lo porta fin sulle vette dell''Himalaya, dove Ra''s Al Ghul e il suo fido Ducard lo iniziano alla lotta contro il male. Wayne è deciso a servire la giustizia, e una volta tornato a Gotham trova in Falcone, potente trafficante di droga, e in Crane, altrettanto corrotto psichiatra, due acerrimi nemici, dietro ai quali però pare celarsi qualcuno di ancor più potente. L''unico modo per combatterli è diventare Batman, un simbolo che dia forza e speranza alla gente.', false, 7, '', 'Batman Begins', 2005, 'Christopher Nolan', 'Dramma, Crime, Azione', 140, 'GB', '/y9AuabF1SXnn3xZ0tAJLLhv33Uj.jpg', 'https://www.youtube.com/watch?v=kOrgt0Jq4YU', 7.719, 22010, '2025-12-10', 'liked', 0, NULL, '2025-12-10T19:47:41.879000+00'),
('marco.corradino@gmail.com', 278, 'Le ali della libertà', '/9OxcvTJwZDjQTFvY2NxiwnSrQS6.jpg', 'Siamo nel 1946. Processato per l''omicidio della moglie e del suo amante, Andy, un bancario del New England, viene condannato a un doppio ergastolo e recluso nel penitenziario di Shawshank. All''inizio è vittima delle violenze dei reclusi, poi però diventa il consulente finanziario delle guardie. Scopre così che il direttore falsifica i libri contabili intestando i conti a un fittizio Randall Stevens. Fuggito di prigione attraverso un tunnel costruito negli anni, Andy assume l''identità di Randall Stevens, denuncia il direttore e va in Messico.', false, 8, '', 'The Shawshank Redemption', 1994, 'Frank Darabont', 'Dramma, Crime', 142, 'US', '/zfbjgQE1uSd9wiPTX4VzsLi0rGG.jpg', 'https://www.youtube.com/watch?v=0ly4vMdPBo0', 8.713, 29321, '2025-12-08', 'loved', 0, NULL, '2025-12-08T15:07:04.178000+00'),
('marco.corradino@gmail.com', 280, 'Terminator 2 - Il giorno del giudizio', '/orzgtkWWEHlSMcFm1p74ZvGqdz0.jpg', 'Dieci anni dopo i fatti stravolgenti per Sarah Connor, un altro, più evoluto Terminator viene inviato sulle sue tracce. Stavolta l''obiettivo è il figlio John, il futuro leader della ribellione alle macchine che stanno conquistando il mondo. Anche i ribelli del futuro cercheranno di provvedere alla protezione del ragazzo.', false, 7, '', 'Terminator 2: Judgment Day', 1991, 'James Cameron', 'Azione, Thriller, Fantascienza', 137, 'FR', '/izkMjmhauFx9DjoBQqM5sM5WAwE.jpg', 'https://www.youtube.com/watch?v=y-VtbthUs8U', 8.167, 14817, '2026-09-11', 'liked', 0, NULL, '2026-09-11T17:00:20.813000+00'),
('marco.corradino@gmail.com', 322, 'Mystic River', '/3D5VS7oWduCmwNLNmRClqGKOgZa.jpg', 'Da ragazzini Jimmy Marcus, Sean Devine e Dave Boyle erano inseparabili. Ora, a distanza di molto tempo, i tre si ritrovano in occasione di un tragico evento: la morte della prima figlia di Jimmy. Sean, che fa il poliziotto, indaga sul fatto...', false, 8, '', 'Mystic River', 2003, 'Clint Eastwood', 'Thriller, Dramma, Mistero, Crime', 137, 'US', '/4ycpMe25LYpzGW42U9amyW9gM53.jpg', 'https://www.youtube.com/watch?v=lKq3tKa5aJA', 7.744, 7666, '2026-09-11', 'loved', 0, NULL, '2026-09-11T17:03:37.355000+00'),
('marco.corradino@gmail.com', 334, 'Magnolia', '/eoYw97lhVvQpvTxjHoy4TsBiFY4.jpg', 'Gli ultimi giorni della vita del ricco Earl Partridge significano cambiamenti e confronti, non solo per il moribondo, ma anche per altre otto persone che si trovano d''improvviso a fare i conti con colpe e sentimenti nella San Fernando Valley, in California.', false, 8, '', 'Magnolia', 1999, 'Paul Thomas Anderson', 'Dramma', 193, 'US', '/mFfyE5DPFDqoes4HIcElHc2a15y.jpg', 'https://www.youtube.com/watch?v=y2opw3ZL-lE', 7.7, 3818, '2025-12-10', 'loved', 0, NULL, '2025-12-10T19:50:12.233000+00'),
('marco.corradino@gmail.com', 423, 'Il pianista', '/eZaGrYtMM2FnssT7WD4XfWbWEB8.jpg', 'È la storia di Wladyslaw Szpilman, pianista ebreo polacco, attraverso la Seconda Guerra Mondiale, dall’occupazione di Varsavia all’arrivo dell’Armata Rossa. Il film è diviso in due parti: la prima è incentrata sulla famiglia Szpilman, dall’iniziale mix di stupore e indignazione per le leggi razziali alla reclusione nel ghetto, infine alla deportazione; col treno che parte, e Wladyslaw che rimane giù, inizia la seconda parte, la fuga del pianista, il suo continuo cambiar nascondiglio, sempre a un passo dalla cattura, a mezzo dalla morte, a nessuno dall’orrore che in quegli anni ha avvolto Varsavia – non solo Varsavia.', false, 8, '', 'The Pianist', 2002, 'Roman Polanski', 'Dramma, Guerra', 150, 'FR', '/1XqIhsqnAozznGhxlGdI0GPcCro.jpg', 'https://www.youtube.com/watch?v=Ulh3l7tpI6M', 8.379, 9788, '2025-12-10', 'liked', 0, NULL, '2025-12-10T17:24:35.747000+00'),
('marco.corradino@gmail.com', 424, 'Schindler''s List', '/m0pV0fmMERzCvPVQbLLrPPLl5q1.jpg', 'Tratto dal libro di Thomas Keneally è la vera storia di Oscar Schindler, industriale tedesco, che nel 1938 capisce che è bene legarsi ai comandanti militari. Li frequenta nei locali notturni, offre bottiglie preziose. Quando gli ebrei sono relegati nel ghetto di Cracovia Schindler riesce a farsene assegnare alcune centinaia come operai in una fabbrica di pentole. All''inizio sembra sfruttarli, in realtà li salva. Di fronte alla persecuzione tremenda, il tedesco trasforma quella sua prima iniziativa in una vera missione, fino a comprare letteralmente le vite di quasi milleduecento ebrei (la famosa lista) che sicuramente morirebbero nel campo di Auschwitz.', false, 8, '', 'Schindler''s List', 1993, 'Steven Spielberg', 'Dramma, Storia, Guerra', 195, 'US', '/zb6fM1CX41D9rF9hdgclu0peUmy.jpg', 'https://www.youtube.com/watch?v=SW4eNdZXl7Q', 8.566, 16892, '2025-12-08', 'loved', 0, NULL, '2025-12-08T15:07:14.589000+00'),
('marco.corradino@gmail.com', 429, 'Il buono, il brutto, il cattivo', '/2VTS3wRO59hPEHiXqMOkGaypJGe.jpg', 'Durante la guerra di Secessione, tre spregiudicati avventurieri, cercano di impossessarsi di un carico d''oro che gli permetterebbe di chiudere con la vita da pistoleri. Ma la guerra li costringerà a cambiare i loro piani.', false, 7, '', 'Il buono, il brutto, il cattivo', 1966, 'Sergio Leone', 'Western', 179, 'US', '/Adrip2Jqzw56KeuV2nAxucKMNXA.jpg', 'https://www.youtube.com/watch?v=qMrZBXMGDbU', 8.5, 9277, '2025-12-08', 'liked', 0, NULL, '2025-12-08T15:06:08.282000+00'),
('marco.corradino@gmail.com', 497, 'Il miglio verde', '/kptqTcldosy8JPf75JT16oTYUMB.jpg', 'E'' il racconto che Paul Edgecomb fa all''amica Elaine Connelly in una casa di riposo. Sono passati circa sessanta anni da quando lavorava come capo delle guardie del braccio della morte nel penitenziario di Could Mountain. Durante la grande depressione, nel carcere del sud degli Usa, Edgecomb si occupava di quattro assassini che attendevano di compiere la loro ultima passeggiata lungo il ''Miglio verde'', il corridoio rivestito di linoleum verde che li avrebbe condotti nella stanza della sedia elettrica. Fra questi c''era anche John Coffrey, un ragazzone nero condannato per l''omicidio di due gemelline di nove anni. Nonostante avesse le dimensioni e la forza per uccidere chiunque, Coffrey aveva un carattere semplice e ingenuo: era davvero lui il colpevole?', false, 7, '', 'The Green Mile', 1999, 'Frank Darabont', 'Fantasy, Dramma, Crime', 188, 'US', '/b6HWTOxn1xevvyHU2K9ICvaRU6g.jpg', 'https://www.youtube.com/watch?v=ahpcWXrP9p0', 8.503, 18590, '2026-01-13', 'liked', 0, NULL, '2026-01-13T17:03:36.411000+00'),
('marco.corradino@gmail.com', 510, 'Qualcuno volò sul nido del cuculo', '/hpg2j8FhnnmbiRpoOU09M0sffJu.jpg', 'Candle McMurphy, arrestato per piccoli reati, viene portato in una clinica psichiatrica: tenta di fingersi pazzo per sfuggire al carcere. Qui viene a contatto con gli altri pazienti dei quali diventa ben presto il beniamino: si prende gioco delle sedute di psicoanalisi, si improvvisa telecronista, organizza una piccola gita in barca. L''ospedale è diretto dalla ferrea capoinfermiera, la signorina Ratched che ha organizzato la vita dei pazienti secondo regole di intransigente disciplina.', false, 7, '', 'One Flew Over the Cuckoo''s Nest', 1975, 'Miloš Forman', 'Dramma', 133, 'US', '/6Oa3zTiluBz2W8D2ou1MY16dUiF.jpg', 'https://www.youtube.com/watch?v=-FLAyG93K7k', 8.413, 11068, '2025-12-10', 'liked', 0, NULL, '2025-12-10T17:07:52.117000+00'),
('marco.corradino@gmail.com', 539, 'Psyco', '/tdqX0MWaFHuGwUygYn7j6eluOdP.jpg', 'Marion Crane, impiegata in una società immobiliare, scappa con 40.000$ rubati dalle casse della ditta. Durante la fuga verso casa del fidanzato però, decide di fermarsi nel Motel gestito dal giovane Norman Bates e dalla madre, che però vive rintanata nella casa attigua al Motel stesso.  Il capolavoro di Alfred Hitchcock.', false, 8, '', 'Psycho', 1960, 'Alfred Hitchcock', 'Horror, Thriller, Mistero', 109, 'US', '/mufF1aYvwdpKerhq5R1YrVcbJLY.jpg', 'https://www.youtube.com/watch?v=_GBNVVUlxmU', 8.406, 11240, '2026-09-11', 'liked', 0, NULL, '2026-09-11T17:08:24.630000+00'),
('marco.corradino@gmail.com', 550, 'Fight Club', '/rtNLQ8HbPElzEfrHjrzSr07prKT.jpg', 'Un uomo di trent''anni è insofferente su tutto e la notte non riesce più a dormire. In cerca di qualche luogo dove scaricare la propria ansia si mette a frequentare quei corsi dove gruppi di malati gravi si riuniscono e confessano agli altri le rispettive situazioni. Mentre si lascia andare alla commozione e al pianto di fronte a quello che vede, l''uomo fa la conoscenza prima di Marla Singer poi di Tyler Durden. Lei è una ragazza a sua volta alla deriva, incapace di scelte o decisioni; lui è un tipo deciso e vigoroso con un''idea precisa in testa. Tyler fa saltare per aria l''appartamento dell''uomo e i due vanno a vivere insieme in una casa fatiscente. Deciso a coinvolgerlo nel suo progetto, Tyler lo fa entrare in un ''Fight Club'', uno stanzone sotterraneo dove ci si riunisce per picchiarsi e in questo modo sentirsi di nuovo vivi...', false, 8, '', 'Fight Club', 1999, 'David Fincher', 'Dramma, Thriller', 139, 'DE', '/hZkgoQYus5vegHoetLkCJzb17zJ.jpg', 'https://www.youtube.com/watch?v=FEqp8tSh1F4', 8.438, 31071, '2025-12-10', 'liked', 0, NULL, '2025-12-10T17:07:06.190000+00'),
('marco.corradino@gmail.com', 582, 'Le vite degli altri', '/wDeusk4e4uvigGNx6IYibMOrNks.jpg', 'Nei primi anni Ottanta, il drammaturgo di successo Georg Dreyman e la sua compagna di sempre, la famosa attrice Christa-Maria Sieland, si trasferiscono a Berlino Est. I due sono considerati dalla DDR tra i più importanti intellettuali del regime comunista e sono tenuti in grande considerazione, malgrado in cuor loro Georg e Christa-Maria non siano sempre allineati con la linea del partito. Un giorno il ministro della cultura assiste ad uno spettacolo dell''attrice e se ne innamora. Chiede allora a Gerd Wiesler, uno dei più valorosi agenti della Stasi, di avvicinare la coppia, conoscerla meglio, ed osservare ogni loro spostamento e interesse. Sarà la vita di Gerd ad essere cambiata dal rapporto con lo scrittore.', false, 10, '', 'Das Leben der Anderen', 2006, 'Florian Henckel von Donnersmarck', 'Dramma, Thriller', 137, 'DE', '/g11nKgir3nIhlG2gIDWIvJeR4fz.jpg', 'https://www.youtube.com/watch?v=QQZWblskqXc', 8.039, 4123, '2026-06-03', 'loved', 0, NULL, '2026-06-03T09:35:49.169000+00'),
('marco.corradino@gmail.com', 603, 'Matrix', '/yQZX4scmfYtj4ccKFNGZJlOj1y9.jpg', 'Seguendo un tatuaggio sulla spalla di una ragazza, l''hacker Neo scopre che la cosiddetta "realtà" è solo un impulso elettrico fornito al cervello degli umani da un''intelligenza artificiale. Per sopravvivere alla catastrofe l''umanità ha infatti avuto bisogno delle macchine, ma queste hanno vinto e necessitano degli uomini come fonte di energia. L''illusione in cui li fanno vivere è quindi finalizzata a "coltivarli" meglio. Nessuno è a conoscenza del tempo che è passato da quando il neurosimulatore ha assegnato una data fittizia al tempo. Solo Neo, con l''aiuto del pirata informatico Morpheus e della bella Trinity, può tentare di scoprire la verità, ma non sarà un''impresa facile.', false, 8, '', 'The Matrix', 1999, 'Lana Wachowski', 'Azione, Fantascienza', 136, 'US', '/tlm8UkiQsitc8rSuIAscQDCnP8d.jpg', 'https://www.youtube.com/watch?v=VdZwkM_HWzw', 8.247, 27927, '2026-06-03', 'liked', 0, NULL, '2026-06-03T09:33:31.656000+00'),
('marco.corradino@gmail.com', 637, 'La vita è bella', '/Moz0CzJ44U9L3ADxlVE24LTwY4.jpg', 'Guido, un giovane ebreo amante della vita e della poesia, si reca ad Arezzo con l''amico Ferruccio in cerca di lavoro. Si fa assumere come cameriere dallo zio Eliseo, che gestisce il Grand Hotel, e s''innamora di Dora, un''insegnante promessa sposa all''antipatico fascista Rodolfo. Con l''esuberanza e l''allegria del suo carattere, riesce a vincere le reticenze della maestrina, e a sposarla. Sei anni dopo, probabilmente denunciato dalla suocera che non ha mai digerito il matrimonio, Guido è deportato in un campo di concentramento con lo zio Eliseo e col suo figlioletto, il piccolo Giosuè, mentre Dora, pur non essendo ebrea, decide di seguirli di sua iniziativa.', false, 8, '', 'La vita è bella', 1997, 'Roberto Benigni', 'Commedia, Dramma', 116, 'IT', '/6aNKD81RHR1DqUUa8kOZ1TBY1Lp.jpg', 'https://www.youtube.com/watch?v=ao71lV1NJsc', 8.441, 13658, '2026-01-14', 'liked', 0, NULL, '2026-01-14T08:36:49.604000+00'),
('marco.corradino@gmail.com', 680, 'Pulp Fiction', '/9p10J9Xp7MuaVac56g8BwAuXEsA.jpg', 'Le vite di due gangster, di un pugile e della moglie di un potente boss della malavita finiscono per intrecciarsi in una paradossale storia di violenza, vendetta e redenzione.', false, 8, '', 'Pulp Fiction', 1994, 'Quentin Tarantino', 'Thriller, Crime, Commedia', 154, 'US', '/suaEOtk1N1sgg2MTM7oZd2cfVp3.jpg', 'https://www.youtube.com/watch?v=Q0aYh9a0Tm0', 8.5, 29350, '2025-12-08', 'loved', 0, NULL, '2025-12-08T15:06:43.795000+00'),
('marco.corradino@gmail.com', 745, 'The Sixth Sense - Il sesto senso', '/1Dth4Jbh7FzPguUIddmK43deTCy.jpg', 'Un famoso psichiatra infantile in un momento difficile della propria vita fa amicizia con un bambino che sembra avere dei problemi. Presosi a cuore il caso, l''uomo riesce a entrarvi in confidenza e a scoprire che è disturbato da visioni: il piccolo asserisce infatti di poter vedere la gente morta.', false, 7, '', 'The Sixth Sense', 1999, 'M. Night Shyamalan', 'Mistero, Thriller, Dramma', 107, 'US', '/paUKxrbN2ww0JeT2JtvgAuaGlPf.jpg', 'https://www.youtube.com/watch?v=SHuoJCzP5g0', 7.946, 12482, '2026-02-21', 'liked', 0, NULL, '2026-01-14T08:45:09.169000+00'),
('marco.corradino@gmail.com', 769, 'Quei bravi ragazzi', '/7Ce724ZcEt7Id9EwBFFdXuvDxWA.jpg', 'Henry Hill, figlio di emigranti italo-irlandesi, fin da giovane entra a far parte della piccola mafia dei quartieri poveri di New York. Ma ben presto scopre la ferocia dei boss locali che usano chiamarsi fra di loro "bravi ragazzi"...', false, 8, '', 'GoodFellas', 1990, 'Martin Scorsese', 'Dramma, Crime', 145, 'US', '/gILte6Zd7m1YneIr6MVhh30S9pr.jpg', 'https://www.youtube.com/watch?v=6OCppnXY-dg', 8.454, 13819, '2025-12-08', 'loved', 0, NULL, '2025-12-08T15:05:40.402000+00'),
('marco.corradino@gmail.com', 807, 'Seven', '/hdQ3mvAMtanWtOuk9Y2hL6h3KRu.jpg', 'Un killer astuto e spietato sta uccidendo a raffica, nei modi più raccapriccianti, personaggi scelti con cura. Sulle sue tracce ci sono il giovane e ambizioso Mills, alla prima missione, e l''esperto Somerset, ormai prossimo alla pensione; personalità opposte che mal si tollerano a vicenda. Imparano a "convivere" man mano che la caccia all''assassino si fa più serrata e il mistero comincia a districarsi.', false, 7, '', 'Se7en', 1995, 'David Fincher', 'Crime, Mistero, Thriller', 128, 'US', '/hkKTtlHjiVUW5XRfkQfl3FmJUfX.jpg', 'https://www.youtube.com/watch?v=hKUABU9uPmw', 8.378, 22345, '2025-12-10', 'liked', 0, NULL, '2025-12-10T17:24:44.221000+00'),
('marco.corradino@gmail.com', 1124, 'The Prestige', '/xKsiJimxRa44FArhlfGHnylrT0i.jpg', 'Due giovani maghi apprendisti, Robert Angier e Alfred Borden, vengono istruiti e seguiti da Cutter, un ingegnere illusionista ed ex mago, ma durante un numero in cui una donna viene legata e messa in una cassa di vetro piena d''acqua, qualcosa va storto e Angier incolperà l''amico dell''accaduto, tentando di vendicarsi. Inizia così un crudele gioco tra i due uomini su chi sia il migliore e la rivalità si trasformerà pian piano in ossessione.', false, 8, 'Ottimo', 'The Prestige', 2006, 'Christopher Nolan', 'Dramma, Mistero, Fantascienza', 130, 'GB', '/yCnJT53HMXAK87xzPAdjdYhZ3JE.jpg', 'https://www.youtube.com/watch?v=R0EX7pO8w50', 8.205, 17001, '2025-12-10', 'loved', 0, NULL, '2025-12-10T19:45:22.753000+00'),
('marco.corradino@gmail.com', 2649, 'The Game - Nessuna regola', '/xYPYjPDP1gT4rQTe6QAn6irVK2j.jpg', 'Nicholas Van Horton è un uomo d''affari che riscuote molto successo e che è abituato a tenere sotto controllo ogni aspetto dei suoi investimenti. La sua vita, fin troppo ordinata, cambia improvvisamente corso nel momento in cui suo fratello Conrad, in occasione del suo compleanno, gli organizza una sorpresa, un vero e proprio gioco di ruolo. Appena entrato nel gioco Nicholas si rende conto che i rischi sono altissimi e scopre di essere tenuto sotto controllo, perfino dentro casa, da cospiratori sconosciuti che lo vogliono annientare.', false, 7, '', 'The Game', 1997, 'David Fincher', 'Dramma, Thriller, Mistero', 123, 'US', '/k7GM13qRYSour3lk90Dq1EwdpoW.jpg', 'https://www.youtube.com/watch?v=MKjph0BRuqc', 7.567, 7100, '2026-01-14', 'liked', 0, NULL, '2026-01-14T08:34:25.144000+00'),
('marco.corradino@gmail.com', 11216, 'Nuovo Cinema Paradiso', '/3hcXpztAe9L6VLpDGwohS01ZSxw.jpg', 'E'' la storia dell''amicizia tra Alfredo, proiezionista del cinematografo parrocchiale del paesino di Giancaldo in Sicilia, e Salvatore, diventato poi da grande affermato regista a Roma. Alla notizia della morte di Alfredo, Salvatore ripercorre nella sua memoria i momenti più significativi di questa amicizia e decide di tornare al suo paese per i funerali.Ma tra le altre sorprese scoprirà che la sala del Nuovo Cinema Paradiso sta per essere abbattuta.', false, 8, '', 'Nuovo Cinema Paradiso', 1988, 'Giuseppe Tornatore', 'Dramma, Romance', 155, 'FR', '/zoVeIgKzGJzpdG6Gwnr7iOYfIMU.jpg', NULL, 8.43, 4659, '2025-12-10', 'loved', 0, NULL, '2025-12-10T17:07:16.361000+00'),
('marco.corradino@gmail.com', 13223, 'Gran Torino', '/eUepSGWIJjXeMAlSnk4CSZKOTfg.jpg', 'Walt Kowalski è un veterano della guerra in Corea e non sopporta che nell''abitazione di fianco alla sua viva una famiglia di asiatici. Le uniche sue passioni, oltre alla birra, sono il suo cane e un''auto modello Gran Torino, che viene sottoposta a continua manutenzione. La sua vita cambia il giorno in cui il giovane vicino Thao, spinto da una gang, si introduce nel suo garage. Walt lo fa fuggire, ma di lì a poco tempo assisterà a una violenta irruzione dei membri della gang con inatteso sconfinamento nella sua proprietà. In quell''occasione sottrarrà Thao alla violenza del branco, ottenendo la riconoscenza della sua famiglia.', false, 8, '', 'Gran Torino', 2008, 'Clint Eastwood', 'Dramma', 116, 'US', '/sP4vNXFhPviUJevrD7X8fJV1OD1.jpg', 'https://www.youtube.com/watch?v=D6wR1SGIAmo', 7.988, 11805, '2026-09-11', 'liked', 0, NULL, '2026-09-11T17:04:21.677000+00'),
('marco.corradino@gmail.com', 22954, 'Invictus - L''invincibile', '/kdX7c7Dsakmb54u1WfT5m584jNQ.jpg', 'Le dolorose tappe del cammino che ha portato Nelson Mandela alla presidenza del Sudafrica spingendolo a collaborare col capitano della squadra nazionale di rugby, François Pienaar, per tenere unito il paese dopo l''Apartheid.', false, 8, '', 'Invictus', 2009, 'Clint Eastwood', 'Dramma, Storia', 134, 'US', '/vHwrJiFc74Lb8D0Trvdc0v04gRK.jpg', 'https://www.youtube.com/watch?v=w_RJS-fURwE', 7.179, 4426, '2026-09-11', 'liked', 0, NULL, '2026-09-11T17:06:21.746000+00'),
('marco.corradino@gmail.com', 49026, 'Il cavaliere oscuro - Il ritorno', '/y4vxHe911huzlN2df5uqdVJlLg5.jpg', 'Sono passati otto anni da quando Batman è svanito nella notte, trasformandosi in un istante da eroe a fuggitivo. Prendendosi la colpa della morte del procuratore Harvey Dent, il Cavaliere oscuro ha sacrificato tutto per ciò che lui e il Commissario Gordon speravano fosse un bene superiore. Per un po’ di tempo la bugia ha funzionato e l’attività criminale di Gotham City è stata schiacciata dal peso della legge anti-criminale Dent Act. Ma tutto cambierà con l’arrivo di un’astuta ladra con un misterioso piano. Ma molto più pericoloso è l’arrivo di Bane, un terrorista mascherato i cui spietati piani per Gotham costringono Bruce a uscire dal suo esilio auto imposto. Ma anche se indossa di nuovo il mantello e il cappuccio, Batman potrebbe non essere così forte da fermare Bane.', false, 7, '', 'The Dark Knight Rises', 2012, 'Christopher Nolan', 'Azione, Crime, Dramma, Thriller', 165, 'GB', '/y2DB71C4nyIdMrANijz8mzvQtk6.jpg', 'https://www.youtube.com/watch?v=XaO9KAIEDdg', 7.789, 23755, '2025-12-10', 'liked', 0, NULL, '2025-12-10T19:48:15.099000+00'),
('marco.corradino@gmail.com', 60243, 'Una separazione', '/xynnD3ogRv3DEaSfLYjmsa7PX5j.jpg', 'Nader e Simin hanno ottenuto il visto per lasciare l''Iran ma Nader si rifiuta di partire e abbandonare il padre affetto da Alzheimer. Simin intende chiedere il divorzio per partire lo stesso con la figlia Termeh e, nel frattempo, torna a vivere da sua madre. Nader deve assumere una giovane donna, Razieh, che possa prendersi cura del padre mentre lui lavora, ma non sa che la donna, molto religiosa, non solo è incinta ma sta anche lavorando senza il permesso del marito. Ben presto Nader si troverà coinvolto in una rete di bugie, manipolazioni e confronti, mentre la sua separazione va avanti e sua figlia deve scegliere da che parte stare e quale futuro avere...', true, NULL, '', 'جدایی نادر از سیمین', 2011, 'Asghar Farhadi', 'Dramma', 123, 'IR', '/vSQ2FK4LzevXeHeXvEHb7t4I0SW.jpg', 'https://www.youtube.com/watch?v=gCX2oPDcoj8', 7.902, 1971, NULL, NULL, 0, NULL, '2026-07-18T16:39:29.630000+00'),
('marco.corradino@gmail.com', 68722, 'The Master', '/japQvZ7z0wPvRQdLd9xxI7N8Y4P.jpg', 'Freddie Quell è un soldato uscito dalla Seconda Guerra Mondiale con il sistema nervoso a pezzi. A poco servono le cure che l''esercito gli offre, se non a rendere esplicita un''ossessione per il sesso. A ciò si aggiunge un forte interesse per l''alcol che si traduce in misture che lui stesso si prepara e che offre agli altri con esiti non sempre positivi. Finché un giorno, in modo del tutto casuale, Freddie incontra Lancaster Dodd. Costui ha inventato un metodo di introspezione che sperimenta sul disturbato Marine, il quale sembra trarne giovamento. Da quel momento ha inizio un sodalizio che li vedrà percorrere insieme un lungo tratto di strada. Anche se il loro viaggio finirà con l''offrire loro esiti assolutamente diversi.', true, NULL, '', 'The Master', 2012, 'Paul Thomas Anderson', 'Dramma', 137, 'US', '/wgXjsX4taUwMdr5AkOOnkvhFBBr.jpg', 'https://www.youtube.com/watch?v=xr8b9PNt9Bk', 7.115, 3172, NULL, NULL, 0, NULL, '2025-12-10T19:50:59.510000+00'),
('marco.corradino@gmail.com', 157336, 'Interstellar', '/bMKiLh0mES4Uiococ240lbbTGXQ.jpg', 'In seguito alla scoperta di un cunicolo spazio-temporale, un gruppo di esploratori si avventura in una eroica missione per tentare di superare i limiti della conquista spaziale e oltrepassare le distanze che fino a quel momento avevano reso impraticabili i viaggi interstellari. L''obiettivo è quello di trovare nuovi luoghi dove coltivare il granoturco, l''unica coltivazione rimasta dopo un drastico cambiamento climatico che ha colpito soprattutto l''agricoltura.', false, 7, '', 'Interstellar', 2014, 'Christopher Nolan', 'Avventura, Dramma, Fantascienza', 169, 'GB', '/5XNQBqnBwPA9yT0jZ0p3s8bbLh0.jpg', 'https://www.youtube.com/watch?v=gnOCZhluoow', 8.463, 38349, '2025-12-08', 'liked', 0, NULL, '2025-12-08T15:06:14.106000+00'),
('marco.corradino@gmail.com', 244786, 'Whiplash', '/jQwkXN38AGrK2s3LJqxZow1Ic7z.jpg', 'Andrew studia batteria jazz nella più prestigiosa ed importante scuola di musica di New York, è al suo primo anno e già viene notato da Terence Fletcher, temutissimo e inflessibile insegnante che a sorpresa lo vuole nella propria band. Il ragazzo è eccitato dalla possibilità ma non sa che in realtà sarà un inferno di prove, esercizi e umiliazioni come non pensava fosse possibile. Gli standard richiesti da Fletcher sono mostruosi e progressivamente alienano sempre di più Andrew dalle altre parti della sua vita.', false, 8, '', 'Whiplash', 2014, 'Damien Chazelle', 'Dramma, Musica', 107, 'US', '/1kuYEvLkX2nTkbfzN6X0w0xQFQU.jpg', 'https://www.youtube.com/watch?v=bzGzdWUy7HU', 8.375, 16111, '2025-12-10', 'loved', 0, NULL, '2025-12-10T17:08:04.503000+00'),
('marco.corradino@gmail.com', 306947, 'The Invitation', '/qs0aBlZ0Cw9eJ8SxG4wPd44CBPm.jpg', 'Will ed Eden un tempo si amavano. Dopo aver perso tragicamente il loro figlio, Eden è scomparsa prima di ripresentarsi due anni dopo, di punto in bianco, con un nuovo marito. Totalmente diversa da prima, Eden è stranamente cambiata e ha intenzione di riallacciare i rapporti con Will e con tutti coloro che si era lasciata alle spalle. Nel corso di una cena in una casa che una volta era sua, Will in preda ai tormenti si convince che Eden e i suoi nuovi amici hanno in mente un misterioso e terrificante piano.', true, NULL, '', 'The Invitation', 2016, 'Karyn Kusama', 'Thriller, Horror', 90, 'US', '/UT0FaX3djSmvphvDopomPNWXIQ.jpg', 'https://www.youtube.com/watch?v=aZ46somwgF4', 6.427, 2782, NULL, NULL, 0, NULL, '2026-01-14T08:47:28.365000+00'),
('marco.corradino@gmail.com', 320006, 'Taxi Teheran', '/6tIsAtZWm2eriTIzAisrP3Hr4UH.jpg', 'Un taxi attraversa le strade di Teheran in un giorno qualsiasi. Passeggeri di diversa estrazione sociale salgono e scendono dalla vettura. Alla guida non c''è un conducente qualsiasi ma Jafar Panahi stesso impegnato a girare un altro film ''proibito''.  Panahi è stato condannato dalla ''giustizia'' iraniana a 20 anni di proibizione di girare film, scrivere sceneggiature e rilasciare interviste, pena la detenzione per sei anni. Ma non c''è sentenza che possa impedire ad un artista di essere se stesso ed ecco allora che il regista ha deciso di continuare a sfidare il divieto e ancora una volta ci propone un''opera destinata a rimanere quale testimonianza di un cinema che si fa militante proprio perché non fa proclami ma mostra la quotidianità del vivere in un Paese in cui le contraddizioni si fanno sempre più stridenti.', true, NULL, '', 'تاکسی', 2015, 'Jafar Panahi', 'Commedia, Dramma', 82, 'IR', '/677ohgE1vEEMSIHZILT19z4rf58.jpg', 'https://www.youtube.com/watch?v=OgH5d40fSYA', 7.041, 460, NULL, NULL, 0, NULL, '2026-01-14T08:46:47.541000+00'),
('marco.corradino@gmail.com', 363676, 'Sully', '/eYu0WQabgAv5N2rFeZxKYiDLnCz.jpg', 'Il 15 gennaio 2009, il mondo assiste al "Miracolo dell''Hudson" quando il capitano "Sully" Sullenberger atterra in emergenza col suo aereo nelle acque gelide del fiume Hudson, salvando la vita a tutti i 155 passeggeri presenti a bordo. Tuttavia, anche se Sully viene elogiato dall''opinione pubblica e dai media, considerando la sua impresa eroica senza precedenti, delle indagini minacciano di distruggere la sua reputazione e la sua carriera.', false, 8, '', 'Sully', 2016, 'Clint Eastwood', 'Dramma, Storia', 96, 'US', '/oQ024BtJgArg8WI4zfuc2vkCJno.jpg', 'https://www.youtube.com/watch?v=8-r8soVu1D8', 7.205, 7867, '2019-02-11', 'liked', 0, NULL, '2026-09-11T17:05:54.540000+00'),
('marco.corradino@gmail.com', 374720, 'Dunkirk', '/sInkpq76Q9L3JOEXEOVEQeJTjGl.jpg', 'Il film, ambientato durante la Seconda Guerra Mondiale, racconta la drammatica evacuazione verso la Gran Bretagna di centinaia di migliaia di soldati alleati dalla spiaggia di Dunkerque sotto la minaccia dell''esercito tedesco.', false, 7, 'Bello non super', 'Dunkirk', 2017, 'Christopher Nolan', 'Guerra, Azione, Dramma', 106, 'GB', '/ddIkmH3TpR6XSc47jj0BrGK5Rbz.jpg', 'https://www.youtube.com/watch?v=gYQ1d3Rgo5w', 7.45, 17140, '2025-12-10', 'liked', 0, NULL, '2025-12-10T19:44:46.810000+00'),
('marco.corradino@gmail.com', 438631, 'Dune', '/a4DiBbHqXg91YQ8SLGL8otVqeOa.jpg', 'In un distante futuro dell''umanità, il duca Leto Atreides accetta la gestione del pericoloso pianeta di Arrakis, anche noto come Dune, l''unica fonte della sostanza più preziosa dell''universo, "la spezia", una droga che allunga la vita, fornisce capacità mentali sovrumane e rende possibili i viaggi nello spazio. Nonostante Leto sappia che l''offerta è parte di una complessa trappola creata dai suoi nemici, decide di partire per Arrakis, portando con sé la sua concubina Bene Gesserit Lady Jessica, il giovane figlio ed erede Paul, e i suoi più fidati consiglieri. Leto prende il controllo di un''operazione di estrazione della spezia, resa pericolosa dalla presenza di enormi vermi delle sabbie. Un amaro tradimento conduce Paul e Jessica dai Fremen, nativi di Arrakis che vivono nel deserto più profondo.', false, 8, '', 'Dune', 2021, 'Denis Villeneuve', 'Fantascienza, Avventura', 155, 'US', '/wYMbnrdRCREjNLwFlG5SLWzBjui.jpg', 'https://www.youtube.com/watch?v=tVbbaQDN5zs', 7.777, 14173, '2025-12-08', 'loved', 0, NULL, '2025-12-08T15:35:06.843000+00'),
('marco.corradino@gmail.com', 496243, 'Parasite', '/mMM8kcfspicib7AmPTvf97Rarwn.jpg', 'Tutta la famiglia di Ki-taek è senza lavoro. Ki-taek è particolarmente interessata allo stile di vita della ricchissima famiglia Park. Un giorno, suo figlio riesce a farsi assumere dai Park e le due famiglie si ritrovano così intrecciate da una serie di eventi incontrollabili.', false, 7, '', '기생충', 2019, 'Bong Joon Ho', 'Commedia, Thriller, Dramma', 132, 'KR', '/hiKmpZMGZsrkA3cdce8a7Dpos1j.jpg', 'https://www.youtube.com/watch?v=iPOugEDF8tk', 8.496, 19776, '2025-12-08', 'liked', 0, NULL, '2025-12-08T15:06:36.496000+00'),
('marco.corradino@gmail.com', 504172, 'Il corriere - The Mule', '/f4I57t32a68Nl5zol4SZDuF79Eb.jpg', 'Earl Stone, un uomo di circa 80 anni rimasto solo e al verde, è costretto ad affrontare la chiusura anticipata della sua impresa, quando gli viene offerto un lavoro per cui è richiesta la sola abilità di saper guidare un auto. Compito semplice, ma, ciò che Earl non sa è che ha appena accettato di diventare un corriere della droga di un cartello messicano. Nel suo nuovo lavoro è bravo, così bravo che il suo carico diventa di volta in volta più grande e per questo motivo gli viene assegnato un assistente.  Questi non è però l''unico a tenere d''occhio Earl: il misterioso nuovo "mulo" della droga è finito anche nel radar dell''efficiente agente della DEA, Colin Bates. E anche se i suoi problemi di natura finanziaria appartengono ormai al passato, i suoi errori affiorano e si fanno pesanti nella testa, portandolo a domandarsi se riuscirà a porvi rimedio prima che venga beccato dalla legge... o addirittura da qualcuno del cartello stesso.', false, 8, '', 'The Mule', 2018, 'Clint Eastwood', 'Crime, Dramma, Thriller', 116, 'CA', '/h51DdjaDD2aPu1fLHsmpJaaJinS.jpg', 'https://www.youtube.com/watch?v=4W9rnhhZjs4', 6.87, 5472, '2018-02-11', 'loved', 0, NULL, '2026-09-11T17:05:05.357000+00'),
('marco.corradino@gmail.com', 549509, 'The Brutalist', '/LfI6QwtR7HTguzvjLESpc6qNK6.jpg', 'In fuga dall''Europa del dopoguerra, l''architetto visionario László Toth arriva in America per ricostruire la sua vita, il suo lavoro e il suo matrimonio con la moglie Erzsébet dopo essere stato costretto a separarsi durante la guerra da confini e regimi mutevoli. Da solo in un paese nuovo e sconosciuto, László si stabilisce in Pennsylvania, dove il ricco e importante industriale Harrison Lee Van Buren riconosce il suo talento nel costruire. Ma il potere e l''eredità hanno un costo elevato.', false, 8, '', 'The Brutalist', 2024, 'Brady Corbet', 'Dramma, Storia', 215, 'GB', '/hmZnqijPaaACjenDkrbWcCmcADI.jpg', 'https://www.youtube.com/watch?v=zi3_AVjtI1k', 6.972, 1484, '2026-02-21', 'liked', 0, NULL, '2026-01-13T16:36:02.349000+00'),
('marco.corradino@gmail.com', 577922, 'Tenet', '/iKXqUiLFDgeIGozRR6JYRvFmD5A.jpg', 'Il tempo per il nostro mondo sta per scadere, ed alcuni agenti entrano in azione per evitare un evento più catastrofico di una terza Guerra Mondiale o di un Olocausto nucleare. Tenet aprirà le porte giuste – e anche alcune sbagliate – per guardare il mondo con occhi nuovi, sentendolo anziché tentare di comprenderlo…', false, 6, '', 'Tenet', 2020, 'Christopher Nolan', 'Azione, Thriller, Fantascienza', 150, 'GB', '/yY76zq9XSuJ4nWyPDuwkdV7Wt0c.jpg', 'https://www.youtube.com/watch?v=a9YE2jl_07w', 7.177, 10643, '2025-12-10', 'disliked', 0, NULL, '2025-12-10T19:46:55.772000+00'),
('marco.corradino@gmail.com', 593643, 'The Menu', '/zJjONpdoLVBcKiMF8KFbdl1E2da.jpg', 'Margot e Tyler sono una giovane coppia che si reca su una remota ed elitaria isola privata per cenare in un ristorante esclusivo, dove un misterioso chef ha messo a punto un costosissimo e sontuoso menù. Ma i pretenziosi e viziati clienti del locale troveranno alcune scioccanti sorprese ad attenderli.', false, 7, '', 'The Menu', 2022, 'Mark Mylod', 'Commedia, Horror', 107, 'US', '/4vSBj7BYsyuKCx96EJzGyp20WfY.jpg', 'https://www.youtube.com/watch?v=qCvg0yr89Xs', 7.178, 6226, '2026-06-03', 'liked', 0, NULL, '2026-06-03T09:38:21.653000+00'),
('marco.corradino@gmail.com', 648878, 'Eddington', '/7dVObOTg6Irn4ePS79fVDYHQF7V.jpg', '2020, New Mexico. La rivalità tra lo sceriffo di Eddington Joe Cross e il sindaco Ted Garcia si fa sempre più accesa. Tra gelosie legate a una precedente relazione tra Ted e la moglie di Joe, Louise, e contrapposizioni legate alla pandemia da Covid-19, ogni occasione è propizia per un contrasto tra i due. Joe si candida a sindaco per le prossime elezioni contro Ted: quando alle restrizioni della pandemia si aggiungono le tensioni verso la polizia dovute a Black Lives Matter, la situazione degenera e la scintilla potrebbe dar vita a un incendio.', false, 8, '', 'Eddington', 2025, 'Ari Aster', 'Western, Commedia, Crime', 148, 'US', '/5PJkK2iVXRO1ydrtgwuJdevmnOe.jpg', 'https://www.youtube.com/watch?v=i3LIBeswdrw', 6.429, 591, '2026-01-13', 'loved', 0, NULL, '2026-01-13T16:54:11.345000+00'),
('marco.corradino@gmail.com', 687163, 'L''ultima missione: Project Hail Mary', '/xfwpfBtZ255ceVKEj2CK7mmYjF6.jpg', 'L’insegnante di scienze Ryland Grace (Ryan Gosling) si sveglia su un’astronave lontano da casa anni luce e senza alcun ricordo di chi sia o di come sia arrivato lì. Con il riaffiorare della sua memoria, torna alla luce lo scopo della sua missione: risolvere l’enigma della misteriosa sostanza che sta causando il collasso del Sole. Dovrà fare affidamento sia sulle sue conoscenze scientifiche che sulle sue capacità di pensare fuori dagli schemi per salvare dall’estinzione la vita sulla Terra… ma un''inaspettata amicizia gli farà capire che non è solo in questa impresa.', false, 7, '', 'Project Hail Mary', 2026, 'Phil Lord', 'Fantascienza, Avventura', 156, 'US', '/fFyLcR22R4ynrecqjMniKXm0UTp.jpg', 'https://www.youtube.com/watch?v=i6duonsTFFc', 8.7, 6160, '2026-07-18', 'liked', 0, NULL, '2026-07-18T16:38:47.157000+00'),
('marco.corradino@gmail.com', 718032, 'Licorice Pizza', '/bQDv8j0IMpGI4sQAGKeWZDY4wpm.jpg', 'Los Angeles, 1973. Gary Valentine, adolescente intraprendente e fanfarone, incontra Alana Kane, venticinquenne sul cammino dell''indipendenza. Lei gli porge specchio e pettine per la foto dell''annuario scolastico, lui le dichiara il suo amore eterno. Lei rifiuta e lui insiste. In cosa crede Gary? A cosa si oppone Alana? Dieci anni li separano ma tutto sembra unirli. Irresistibilmente attratti l''uno dall''altra, non sanno come amarsi, non sanno nemmeno se si amano o se amano soltanto l''idea di amarsi. Tra choc petrolifero, e crepuscolo della Hollywood classica, il loro ipotetico grande amore parte, avanza, sterza, vaga, sosta, svolta, si riallinea in fondo alla notte e alla San Fernando Valley.', false, 7, '', 'Licorice Pizza', 2021, 'Paul Thomas Anderson', 'Dramma, Commedia, Romance', 133, 'CA', '/hB4ibOHXm1Xl0IbuYVioktDGUWJ.jpg', 'https://www.youtube.com/watch?v=0FIumzj6anI', 7, 2505, '2025-12-10', 'liked', 0, NULL, '2025-12-10T19:49:43.819000+00'),
('marco.corradino@gmail.com', 758866, 'Drive My Car', '/bhW5CK4vrrGB3CemMrtwwkU9vo9.jpg', 'Sebbene non sia ancora in grado di riprendersi dalla scomparsa della moglie, l''attore e regista teatrale Yusuke Kafusu accetta di mettere in scena Zio Vanja a un festival di Hiroshima. Qui, conosce Misaki, una giovane riservata che le è stata assegnata come autista. Nel corso dei loro spostamenti, la crescente sincerità delle loro conversazioni costringe entrambi ad affrontare il loro passato.', true, NULL, '', 'ドライブ・マイ・カー', 2021, 'Ryusuke Hamaguchi', 'Dramma', 179, 'JP', '/r6aqhlmJmu8Dv5E7QYEruaEXKYm.jpg', 'https://www.youtube.com/watch?v=x9M12mz2VNY', 7.436, 1557, NULL, NULL, 0, NULL, '2026-09-11T16:54:34.519000+00'),
('marco.corradino@gmail.com', 798286, 'Beau ha paura', '/xixQ5abpEF0qyvuTcRsND0tmwsv.jpg', 'Beau è un uomo paranoico che non ha mai conosciuto il padre e ha un rapporto tormentato con la madre. Quando scopre che la madre è morta, Beau intraprende un viaggio verso casa che ben presto si trasforma in un’odissea surreale.', true, NULL, '', 'Beau Is Afraid', 2023, 'Ari Aster', 'Commedia, Avventura, Fantasy', 179, 'US', '/atvEgnjjXN5QvFDThXVz4nyU9yi.jpg', 'https://www.youtube.com/watch?v=0e_7RQ_wfDg', 6.7, 1248, NULL, NULL, 0, NULL, '2026-01-13T16:55:45.392000+00'),
('marco.corradino@gmail.com', 812583, 'Wake Up Dead Man - Knives Out', '/db8j0xU82lzWKX0SXrPY5tFrzwA.jpg', 'Il detective Benoit Blanc fa squadra con un giovane prete zelante per indagare su un crimine perfettamente impossibile nella chiesa di una piccola città dal passato oscuro.', false, 7, '', 'Wake Up Dead Man: A Knives Out Mystery', 2025, 'Rian Johnson', 'Thriller, Mistero, Commedia', 145, 'US', '/fiRDzpcJe7qz3yIR43hdXIE3NHv.jpg', 'https://www.youtube.com/watch?v=FceO9g1QvSM', 7.351, 658, '2025-12-19', 'liked', 0, NULL, '2025-12-19T09:21:21.636000+00'),
('marco.corradino@gmail.com', 842924, 'The Life of Chuck', '/oumprkO9bThExP8NwxBIBnvBu2v.jpg', 'Tre atti, tre frammenti apparentemente scollegati che, messi insieme, compongono il ritratto intimo e sorprendente di Charles Krantz, un uomo qualunque al centro di qualcosa di straordinario.', false, 9, '', 'The Life of Chuck', 2025, 'Mike Flanagan', 'Fantasy, Dramma', 111, 'US', '/6e2yeFZgtD7RKpUYEOjj5v7oAUz.jpg', 'https://www.youtube.com/watch?v=q9GJyICd2xM', 7.4, 589, '2025-12-10', 'loved', 0, NULL, '2025-12-10T17:08:15.224000+00'),
('marco.corradino@gmail.com', 858024, 'Hamnet - Nel nome del figlio', '/71KNp6RiOQTbs8Fn1DagrFQrZmx.jpg', 'In un bosco, una giovane donna dorme rannicchiata nella culla formata dalla radice emersa di un albero secolare: è vestita di rosso cupo, accompagnata da un falco che risponde ai suoi richiami, conosce erbe e pozioni, si dice non sia nata da sua madre ma da una donna venuta da lontano. Si chiama Agnes e quando Will la vede se ne innamora subito. Will è il giovane William Shakespeare, che riesce a sposarla nonostante l’ostilità delle famiglie e ad avere con lei tre figli, Susannah e i gemelli Judith e Hamnet. Ma un lutto li colpisce, quando il drammaturgo lavora già a Londra, e Hamnet diventa Hamlet. Tratta dal romanzo del 2020 di Maggie O’Farrell, la storia di Agnes (più che di William), intessuta di magia e femminilità.', false, 8, '', 'Hamnet', 2025, 'Chloé Zhao', 'Dramma, Romance', 126, 'GB', '/yt9m5CiU2MZkQoNl1kqLPODNR4t.jpg', 'https://www.youtube.com/watch?v=q5Ubbd7f5as', 8, 6, '2026-06-03', 'liked', 0, NULL, '2025-12-10T17:21:34.320000+00'),
('marco.corradino@gmail.com', 860508, 'L''uomo dei sussurri', '/yghwNwvMjoHOm4TXHDmqSynbbMv.jpg', 'Dopo la scomparsa del figlio di otto anni, uno scrittore di gialli vedovo chiede aiuto al padre, un ex detective della polizia ormai in pensione con cui aveva interrotto i rapporti, e scopre che il rapimento è collegato al vecchio caso di un serial killer condannato noto come "L''uomo dei sussurri".', false, 6, '', 'The Whisper Man', 2026, 'James Ashcroft', 'Crime, Dramma, Thriller', 111, 'US', '/xSJJQeAp9GBFmiKusysTRG6jQjt.jpg', 'https://www.youtube.com/watch?v=SUJaBLkAhQE', 6.8, 587, '2026-09-01', 'liked', 0, NULL, '2026-09-11T17:09:33.448000+00'),
('marco.corradino@gmail.com', 872585, 'Oppenheimer', '/aIwI6oRraxbOetNUuMIoQ3C99cg.jpg', 'La storia del ruolo di J. Robert Oppenheimer, i quali studi condussero alle scoperte legate alla bomba atomica, con il conseguente utilizzo durante le stragi di Hiroshima e Nagasaki durante la Seconda Guerra Mondiale.', false, 6, '', 'Oppenheimer', 2023, 'Christopher Nolan', 'Dramma, Storia', 189, 'GB', '/ycnO0cjsAROSGJKuMODgRtWsHQw.jpg', 'https://www.youtube.com/watch?v=AByfwXr_JXs', 8, 11030, '2025-12-10', 'liked', 0, NULL, '2025-12-10T19:44:14.731000+00'),
('marco.corradino@gmail.com', 936075, 'Michael', '/xUjMqG7GH6md8qX5e3MyLAzAYSZ.jpg', 'La storia di Michael Jackson oltre la musica, il suo viaggio dalla scoperta del suo straordinario talento come protagonista dei Jackson Five all''artista precursore la cui ambizione creativa ha alimentato un''incessante ricerca per diventare il più grande intrattenitore del mondo. Seguendo la sua vita fuori dal palco e alcune delle performance più iconiche degli inizi della sua carriera da solista, il film offre al pubblico un posto in prima fila a Michael Jackson come mai prima d''ora.', true, NULL, '', 'Michael', 2026, 'Antoine Fuqua', 'Musica, Dramma', 127, 'US', '/ufSwlnECLoUbBjPrFqEQcWBzHwc.jpg', 'https://www.youtube.com/watch?v=MDfdC2ubOek', 8.646, 4298, NULL, NULL, 0, NULL, '2026-09-11T16:59:32.796000+00'),
('marco.corradino@gmail.com', 950028, 'The Invite - Il piacere è tutto nostro', '/p9kaEC6mE6oNFhZjkbA1ALuvv2q.jpg', 'Il matrimonio di Joe e Angela è ormai logorato dalla routine, ma quando invitano a cena i loro enigmatici vicini di casa, una coppia affascinante e spregiudicata, la serata – e la loro relazione – prenderà una piega inaspettata.', true, NULL, '', 'The Invite', 2026, 'Olivia Wilde', 'Dramma, Commedia', 107, 'US', '/kLA1GqiOEyVgXxgNqLoCr7bYcqu.jpg', 'https://www.youtube.com/watch?v=xVn866BbWAU', 7.7, 67, NULL, NULL, 0, NULL, '2026-07-18T16:38:06.075000+00'),
('marco.corradino@gmail.com', 969681, 'Spider-Man: Brand New Day', '/vKHjwe9tSPWSkiv3m8Iq1nVedOT.jpg', 'Sono trascorsi quattro anni dagli eventi di No Way Home e Peter è ormai un adulto che vive completamente da solo, essendosi volontariamente cancellato dalla vita e dai ricordi di coloro che ama. Combattendo il crimine in una New York che non conosce più il suo nome, si è dedicato interamente alla protezione della sua città. Uno Spider-Man a tempo pieno. Ma con l''intensificarsi delle richieste, la pressione innesca una sorprendente evoluzione fisica che minaccia la sua stessa esistenza, mentre, una strana nuova serie di crimini, dà origine a una delle minacce più potenti che abbia mai affrontato.', false, 7, '', 'Spider-Man: Brand New Day', 2026, 'Destin Daniel Cretton', 'Fantascienza, Azione, Avventura', 144, 'US', '/qeQJx07rK2xm8SD2sJxFKhE7gs0.jpg', 'https://www.youtube.com/watch?v=W2OheZ8Pj74', 7.857, 2573, '2026-09-11', 'liked', 0, NULL, '2026-09-11T16:57:36.705000+00'),
('marco.corradino@gmail.com', 972119, 'Making Of', '/6KF7BEOTi9iQkfiZvVUyKiQ1t5q.jpg', 'Simon, un noto regista francese, inizia a girare il suo prossimo film. Una storia di lavoratori che lottano per proteggere la loro fabbrica dal trasferimento. Ma niente va come previsto... La sua produttrice Viviane vuole riscrivere il finale e minaccia di tagliare il budget; la sua troupe va in sciopero; la sua vita personale è in rovina; e per peggiorare le cose, il suo attore principale Alain è un idiota egocentrico. Joseph, una comparsa che vuole entrare nell''industria cinematografica, accetta di dirigere la realizzazione e di girare il dietro le quinte. Prende molto sul serio il suo ruolo e inizia a seguire la troupe, catturando tutto questo caos... Ciò che segue è la prova che la realizzazione a volte può essere molto meglio del film stesso!', true, NULL, '', 'Making Of', 2024, 'Cédric Kahn', 'Commedia, Dramma', 119, 'BE', '/sIfjszR9RhjgzvfzV5AvQfvjVlg.jpg', NULL, 5.695, 141, NULL, NULL, 0, NULL, '2026-01-13T17:11:58.103000+00'),
('marco.corradino@gmail.com', 1054867, 'Una battaglia dopo l’altra', '/i9X9Yhwp53ndpyydMIIOrIXNS8m.jpg', 'Un gruppo di ex rivoluzionari si riunisce quando un loro perfido nemico riemerge dal loro passato, dopo sedici anni di silenzio. Il gruppo avrà il duro compito di salvare la figlia di uno di loro, prima che accada l''inevitabile.', false, 7, 'Non male ma si perde nel finale..', 'One Battle After Another', 2025, 'Paul Thomas Anderson', 'Thriller, Crime, Azione', 162, 'US', '/zpEWFNqoN8Qg1SzMMHmaGyOBTdW.jpg', 'https://www.youtube.com/watch?v=OD0Hrp3-J2c', 7.5, 1792, '2025-12-07', 'liked', 0, NULL, '2025-12-08T16:27:23.763000+00'),
('marco.corradino@gmail.com', 1058424, 'Hope', '/ptqlN6mDIAqJjVA86J5eOoG82zc.jpg', 'I rinforzi sono stati richiamati per fronteggiare i devastanti incendi boschivi e ogni comunicazione con l’esterno è stata interrotta. Nel piccolo posto di polizia di Hope, il comandante Bum-seok e l’agente Sung-ae lottano per proteggere un villaggio popolato quasi esclusivamente da anziani. Nel frattempo, tra le montagne, Sung-ki e gli abitanti del luogo partono sulle tracce della misteriosa creatura, ma la battuta di caccia si trasforma presto in un incubo e diventano loro stessi prede.', true, NULL, '', '호프', 2026, 'Na Hong-jin', 'Fantascienza, Mistero, Azione', 157, 'KR', '/o1UvmHqE2fh0Z62wls5bdrNtBN2.jpg', 'https://www.youtube.com/watch?v=uV3s51ivuVI', 8.1, 37, NULL, NULL, 0, NULL, '2026-09-11T16:57:21.099000+00'),
('marco.corradino@gmail.com', 1062722, 'Frankenstein', '/zxPLe88dEW3i2RTGAQixbKmZATz.jpg', 'Il dottor Victor Frankenstein, uno scienziato geniale ma egoista, dà vita a una creatura in un mostruoso esperimento che porterà alla rovina sia del creatore che della sua tragica creazione.', false, 7, '', 'Frankenstein', 2025, 'Guillermo del Toro', 'Dramma, Fantasy, Horror', 150, 'US', '/hpXBJxLD2SEf8l2CspmSeiHrBKX.jpg', 'https://www.youtube.com/watch?v=tbo4UP9HlNY', 7.776, 2115, '2025-12-08', 'liked', 0, NULL, '2025-12-08T15:17:12.783000+00'),
('marco.corradino@gmail.com', 1106739, 'Giurato numero 2', '/zZUQtWNFI86rMoos1cwoGoI0rKo.jpg', 'Justin Kemp, giovane uomo con un passato alcolico e un futuro da papà - la moglie aspetta la loro bambina -, è convocato come giurato in un sordido caso di omicidio alle porte di Savannah, in Georgia. La vittima, Kendall Carter, è stata presumibilmente picchiata a morte e abbandonata in un fosso dopo una violenta discussione col suo ragazzo, membro pentito di una gang di quartiere. Il colpevole ideale per i dodici giurati e per il procuratore della contea in piena campagna elettorale. Faith Killebrew espone i fatti e la vertigine sale. Justin, giurato numero 2, realizza progressivamente la propria colpevolezza nella tragedia avvenuta un anno prima, nel cuore della notte, sulla stessa strada dove si era convinto di aver investito un cervo. Sotto una pioggia battente di ricordi, il marito perfetto si scopre omicida involontario e si ritrova difronte a un dilemma morale: confessare, scagionando l''imputato, o sottrarsi alla giustizia, condannando un innocente?', false, 8, '', 'Juror #2', 2024, 'Clint Eastwood', 'Dramma, Thriller', 114, 'US', '/9Qq8InnodUYs8zdam8Zj967i6RO.jpg', 'https://www.youtube.com/watch?v=9bkpCa0ZgE8', 6.895, 2630, '2026-09-11', 'liked', 0, NULL, '2026-09-11T17:01:55.926000+00'),
('marco.corradino@gmail.com', 1109148, 'La quattordicesima domenica del tempo ordinario', '/sAY3vkg5PvT0tQPeml4NSkrRKkj.jpg', 'Bologna, anni 70. Marzio, Samuele e Sandra sono giovanissimi e ognuno ha un suo sogno da realizzare. La musica, la moda, o forse la carriera. I due ragazzi, amici per la pelle, fondano il gruppo musicale I Leggenda e sognano il successo. Sandra è un fiore di bellezza e aspira a diventare indossatrice. Qualche anno dopo, nella quattordicesima domenica del tempo ordinario, Marzio sposa Sandra mentre Samuele suona l’organo. Quella ‘quattordicesima domenica’ diventa il titolo di una loro canzone, la sola da loro incisa, la sola ad essere diffusa da qualche radio locale. Poi un giorno di quei meravigliosi anni novanta in cui tutto sembra loro possibile, si appalesa all’improvviso la burrasca, un vento contrario e ostile che tutto spazza via. Li ritroviamo 35 anni dopo. Cosa è stato delle loro vite, dei loro rapporti? Ma soprattutto cosa ne è stato dei loro sogni?', true, NULL, '', 'La quattordicesima domenica del tempo ordinario', 2023, 'Pupi Avati', 'Dramma', 98, 'IT', '/u0VxdMAN70RoBDxuxbVQ9SEJA47.jpg', 'https://www.youtube.com/watch?v=uzhxcEoYGaM', 5.5, 48, NULL, NULL, 0, NULL, '2026-06-03T09:47:12.434000+00'),
('marco.corradino@gmail.com', 1119449, 'Good Luck, Have Fun, Don''t Die', '/af7yguGbWQyvYtk6QCD5l4yBbKN.jpg', 'Un uomo sposato che passa troppo tempo con un gioco di ruolo fantasy online incontra un uomo proveniente dal futuro con uno strano piano.', false, 5, '', 'Good Luck, Have Fun, Don''t Die', 2026, 'Gore Verbinski', 'Fantascienza, Azione, Avventura, Commedia', 134, 'US', '/yjOSpDQe8tzr8easpjTFVoQXsOX.jpg', NULL, 7.5, 17, '2026-09-11', 'disliked', 0, NULL, '2026-02-21T12:05:10.250000+00'),
('marco.corradino@gmail.com', 1122573, 'In the Grey', '/uLWKONHP3GTqMaxhEt0NedkGybl.jpg', 'Una squadra segreta di agenti speciali capaci di muoversi abilmente nella “zona grigia” tra potere, denaro e violenza, deve recuperare una fortuna da un miliardo di dollari. Quando il piano devia improvvisamente dal percorso previsto, la missione si trasforma in una corsa senza regole, dove ogni alleanza è fragile e ogni scelta può essere fatale.', false, 6, '', 'In the Grey', 2026, 'Guy Ritchie', 'Azione, Thriller', 97, 'GB', '/qcIKxhqGMIj8uujsSoSMZWr8QqU.jpg', 'https://www.youtube.com/watch?v=L1lLc3kn1I8', 7.572, 921, '2026-09-11', 'disliked', 0, NULL, '2026-09-11T16:58:50.239000+00'),
('marco.corradino@gmail.com', 1124566, 'Sentimental Value', '/8fCqMWoJeW1pFVHx5LnE25iv0K2.jpg', 'La storia di Gustav, celebre regista, che dopo molti anni di assenza, fa ritorno nella vita delle sue due figlie, Agnès e Nora. Gustav propone a Nora, attrice teatrale di grande talento, di interpretare il ruolo della loro madre nel suo prossimo film. Lei rifiuta, ferma e orgogliosa. Il regista allora affida il ruolo a una giovane star di Hollywood, Rachel Kempf, risvegliando vecchie ferite e segreti mai del tutto sopiti all’interno della casa di famiglia…', true, NULL, '', 'Affeksjonsverdi', 2025, 'Joachim Trier', 'Dramma', 135, 'TR', '/mDIMSMXFkOXUyQ2lnmeBu6kDUCH.jpg', NULL, 7.6, 125, NULL, NULL, 0, NULL, '2026-01-13T16:33:53.499000+00'),
('marco.corradino@gmail.com', 1137844, 'Mayday', '/hEPE2DP26os4LRcajwfR7l3UOv6.jpg', 'Durante la Guerra Fredda, un pilota della Marina in missione segreta, è in trappola oltre le linee nemiche. L’unica possibilità è allearsi con un eccentrico ex agente del KGB.', false, 7, '', 'Mayday', 2026, 'Jonathan Goldstein', 'Azione, Commedia', 111, 'US', '/4gyx49ibwQslyrwuUS1c58PJEEd.jpg', NULL, 7.9, 395, '2026-09-11', 'liked', 0, NULL, '2026-09-11T16:57:51.954000+00'),
('marco.corradino@gmail.com', 1151272, 'Sirāt', '/edEDZwU3kZerqdylZsyCn7feH23.jpg', 'Luis con il giovane figlio Esteban si aggira in un rave party mostrando una foto della figlia Mar della quale ha perso da alcuni mesi le tracce e che vorrebbe trovare. Nessuno la conosce ma, nel corso della ricerca, l''uomo fa delle conoscenze che, dopo la chiusura della festa da parte dei militari, lo indirizzano verso un altro rave. Il viaggio non sarà dei più facili e non solo per le asperità del terreno.', true, NULL, '', 'Sirāt', 2025, 'Oliver Laxe', 'Dramma, Thriller, Musica', 115, 'ES', '/c6LXcv9D70NpftZX1j0Z3umXhoK.jpg', 'https://www.youtube.com/watch?v=HC4Qcdj5HKI', 6.866, 316, NULL, NULL, 0, NULL, '2026-01-13T20:14:57.075000+00'),
('marco.corradino@gmail.com', 1208348, 'Rental Family - Nelle vite degli altri', '/4OchXepJLKSeFrLdd3Rk6Wj0H5R.jpg', 'Philip Vandarpleog è un attore americano che vive da otto anni a Tokyo, in Giappone, che considera ormai casa propria. Un tempo celebre perché interpretava un grosso tubetto di dentifricio, supereroe di una pubblicità popolarissima, adesso passa da un’audizione all’altra, mentre il suo agente lo manda a fare la comparsa in eventi come matrimoni e funerali. Ed è proprio a un finto funerale che Philip incontra Shinji, il capo di Rental Family, un’agenzia che procura attori per impersonare parenti e amici che non esistono, e lo scrittura: Philip diventa un giornalista amico di un anziano attore, il padre assente di una bambina sino-americana, il compagno di giochi di un appassionato di videogame.', true, NULL, '', 'Rental Family', 2025, 'Hikari', 'Dramma, Commedia', 110, 'US', '/euoXeFAOt9o7yAWA9zGZk7DdZWZ.jpg', 'https://www.youtube.com/watch?v=lbzrNeXJmOc', 7.842, 408, NULL, NULL, 0, NULL, '2026-02-21T12:05:06.276000+00'),
('marco.corradino@gmail.com', 1220564, 'L''agente segreto', '/hQWzqAQ798fBOzQZ7cuLjTOLqCI.jpg', 'Brasile, 1977. Marcelo è in fuga. Raggiunge Recife durante la settimana del Carnevale per riabbracciare il figlio, ma scopre presto che la città non è l’ameno rifugio che aveva immaginato: sotto la superficie festosa pulsa una realtà soffocante, carica di tensione, violenza e pericolo.', false, 8, '', 'O Agente Secreto', 2025, 'Kleber Mendonça Filho', 'Crime, Dramma, Thriller', 161, 'BR', '/nnx7q1ucLOfFrpAYvGmSEtbWf3L.jpg', 'https://www.youtube.com/watch?v=b5P3t1y06wM', 7.9, 140, '2026-06-03', 'liked', 0, NULL, '2026-01-13T16:33:14.546000+00'),
('marco.corradino@gmail.com', 1233413, 'I peccatori', '/gGhvLVcdWQanE1XuPkC3iE4PJN9.jpg', 'Tornati nella regione natia con un discreto bottino e con abbondanti alcolici dalla malavita di Chicago, i gemelli Smoke e Stack trasformano una baracca in un locale di ballo e gioco clandestino per la popolazione nera. La festa notturna innesca una gioia contagiosa, ma presto si avvicinano tre bianchi che chiedono insistentemente di poter entrare. Sarà presto chiara la loro intenzione.', false, 7, '', 'Sinners', 2025, 'Ryan Coogler', 'Horror, Azione, Thriller', 137, 'US', '/nAxGnGHOsfzufThz20zgmRwKur3.jpg', 'https://www.youtube.com/watch?v=IptoBQg6cvo', 7.496, 4570, '2026-06-03', 'liked', 0, NULL, '2026-06-03T09:33:45.603000+00'),
('marco.corradino@gmail.com', 1272837, '28 anni dopo - Il tempio delle ossa', '/yNM4qb9F53nmwI8Lux1xfJ1dqoA.jpg', 'Il dottor Kelson si ritrova coinvolto in una nuova e sconvolgente relazione, con conseguenze che potrebbero cambiare il mondo così come lo conoscono, e l''incontro di Spike con Jimmy Crystal si trasforma in un incubo da cui non può sfuggire.', true, NULL, '', '28 Years Later: The Bone Temple', 2026, 'Nia DaCosta', 'Horror, Thriller, Fantascienza', 115, 'GB', '/dT1p0K1szMAUBuE2bibouDQdNb8.jpg', 'https://www.youtube.com/watch?v=qOjmK95mM_E', 8.2, 5, NULL, NULL, 0, NULL, '2026-01-13T16:39:58.130000+00'),
('marco.corradino@gmail.com', 1275779, 'Disclosure Day', '/2HfLCkrCc7mnT15lp8tfZag1a9L.jpg', 'Se scoprissi che non siamo soli, se qualcuno te lo mostrasse, te lo dimostrasse, questo ti spaventerebbe?', false, 7, '', 'Disclosure Day', 2026, 'Steven Spielberg', 'Fantascienza, Thriller', 146, 'US', '/IRdft2HxHy9joDQMxB1tGFI2qP.jpg', 'https://www.youtube.com/watch?v=POR6dISht_8', 6.7, 891, '2026-07-18', 'liked', 0, NULL, '2026-07-18T16:38:57.465000+00'),
